mod support;
use axum::{body::{Body,to_bytes},http::{Request,StatusCode}};
use tower::ServiceExt;use serde_json::{Value,json};
use video_kadr_backend::{state::AppState,model::JobStatus};
fn post(uri:&str,body:Value,token:Option<&str>)->Request<Body>{let mut r=Request::builder().method("POST").uri(uri).header("content-type","application/json");if let Some(token)=token{r=r.header("authorization",format!("Bearer {token}"));}r.body(Body::from(serde_json::to_vec(&body).unwrap())).unwrap()}
async fn wait(state:&AppState,id:&str)->video_kadr_backend::model::Job{tokio::time::timeout(std::time::Duration::from_secs(30),async{loop{let job=state.get_job(id).await.unwrap().unwrap();if matches!(job.status,JobStatus::Done|JobStatus::Error|JobStatus::Cancelled){return job}tokio::time::sleep(std::time::Duration::from_millis(10)).await;}}).await.expect("analysis terminal")}
async fn submit(app:&axum::Router,input:&Value,token:&str)->String{let response=app.clone().oneshot(post("/api/compositions/filmcraft/analysis-jobs",input.clone(),Some(token))).await.unwrap();let status=response.status();let body:Value=serde_json::from_slice(&to_bytes(response.into_body(),1024*1024).await.unwrap()).unwrap();assert_eq!(status,StatusCode::ACCEPTED,"{body}");body["jobId"].as_str().unwrap().into()}
#[tokio::test]async fn durable_analysis_warms_preview_enforces_owner_cancel_and_restart(){
 let(state,_dir)=support::make_state(false,false).await;
 let fixture:Value=serde_json::from_reader(flate2::read::GzDecoder::new(std::fs::File::open(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/filmcraft-source-stabilizer.json.gz")).unwrap())).unwrap();let case=&fixture["cases"][0];
 let movie=state.storage.join("sources/analysis.mov");let out=std::process::Command::new("ffmpeg").args(["-nostdin","-v","error","-f","lavfi","-i","testsrc=size=96x64:rate=6:duration=4","-c:v","qtrle","-pix_fmt","argb","-threads","1"]).arg(&movie).output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));
 assert!(state.library.add(video_kadr_backend::library::MediaEntry::from_result("source",&json!({"id":"analysis-source","filename":"analysis.mov","mediaType":"video"}))).await);
 let owner=state.db.register_auth_user("analysis-owner","analysis test password").await.unwrap().unwrap();let outsider=state.db.register_auth_user("analysis-outsider","analysis test password").await.unwrap().unwrap();
 let input=json!({"document":serde_json::to_string(&case["document"]).unwrap(),"sequenceId":"6","timeTicks":case["at"].as_i64().unwrap().to_string(),"captions":false,"sources":{"1":"analysis-source"}});let app=support::router(state.clone());
 assert_eq!(app.clone().oneshot(post("/api/compositions/filmcraft/analysis-jobs",input.clone(),None)).await.unwrap().status(),StatusCode::UNAUTHORIZED);
 let id=submit(&app,&input,&owner.token).await;let job=wait(&state,&id).await;assert_eq!(job.status,JobStatus::Done,"{job:?}");assert_eq!(job.result.unwrap()["ready"],true);assert_eq!(job.progress,Some(100.));
 let hits=state.filmcraft_video_previews.stabilization_path_cache_stats().unwrap().2;
 let response=app.clone().oneshot(post("/api/compositions/filmcraft/preview-frame",input.clone(),Some(&owner.token))).await.unwrap();assert_eq!(response.status(),StatusCode::OK);assert_eq!(state.filmcraft_video_previews.stabilization_path_cache_stats().unwrap().2,hits+1);
 let request=Request::builder().uri(format!("/api/jobs/{id}")).header("authorization",format!("Bearer {}",outsider.token)).body(Body::empty()).unwrap();assert_eq!(app.clone().oneshot(request).await.unwrap().status(),StatusCode::FORBIDDEN);
 for (token,count) in [(&owner.token,1usize),(&outsider.token,0usize)]{let req=Request::builder().uri("/api/compositions/filmcraft/analysis-jobs?limit=1").header("authorization",format!("Bearer {token}")).body(Body::empty()).unwrap();let response=app.clone().oneshot(req).await.unwrap();assert_eq!(response.status(),StatusCode::OK);let page:Value=serde_json::from_slice(&to_bytes(response.into_body(),1024*1024).await.unwrap()).unwrap();assert_eq!(page["jobs"].as_array().unwrap().len(),count);}
 // A queued job must cancel without acquiring execution resources.
 let mut guard=Vec::new();for _ in 0..state.resource_limit(video_kadr_backend::config::resource_classes::ResourceClass::Analysis){guard.push(state.acquire_job_slot(video_kadr_backend::config::resource_classes::ResourceClass::Analysis).await.unwrap());}
 let cancelled=submit(&app,&input,&owner.token).await;assert_eq!(app.clone().oneshot(post(&format!("/api/jobs/{cancelled}/cancel"),json!({}),Some(&outsider.token))).await.unwrap().status(),StatusCode::FORBIDDEN);assert_eq!(app.clone().oneshot(post(&format!("/api/jobs/{cancelled}/cancel"),json!({}),Some(&owner.token))).await.unwrap().status(),StatusCode::OK);assert_eq!(wait(&state,&cancelled).await.status,JobStatus::Cancelled);
 // The durable source snapshot must reject a file changed while queued.
 let changed=submit(&app,&input,&owner.token).await;{use std::io::Write;std::fs::OpenOptions::new().append(true).open(&movie).unwrap().write_all(&[0,0,0,8,b'f',b'r',b'e',b'e']).unwrap();}drop(guard);let failed=wait(&state,&changed).await;assert_eq!(failed.status,JobStatus::Error);assert_eq!(failed.error_kind.as_deref(),Some("validation"));
 // Managed shutdown releases the outbox lease; a new AppState/DB/library resumes work.
 let mut guard=Vec::new();for _ in 0..state.resource_limit(video_kadr_backend::config::resource_classes::ResourceClass::Analysis){guard.push(state.acquire_job_slot(video_kadr_backend::config::resource_classes::ResourceClass::Analysis).await.unwrap());}let recovery=submit(&app,&input,&owner.token).await;
 let requests=state.job_store.active_requests(video_kadr_backend::jobs::JobKind::Stabilization,256).await.unwrap();let payload=serde_json::to_string(&requests.iter().find(|r|r.job.id==recovery).unwrap().payload).unwrap();assert!(!payload.contains(&owner.token));assert!(payload.contains("source_hashes"));
 state.begin_shutdown();drop(guard);assert!(state.wait_for_tasks(std::time::Duration::from_secs(5)).await);assert_eq!(state.get_job(&recovery).await.unwrap().unwrap().status,JobStatus::Pending);
 let restarted=AppState::new_with_runtime(state.storage.clone(),2,(*state.tools).clone(),video_kadr_backend::library::Library::load(state.storage.clone()).await,video_kadr_backend::db::Db::open(&state.storage).await.unwrap(),state.encode_budget.clone(),2).unwrap();restarted.recover_jobs().await;video_kadr_backend::handlers::resume_pending_jobs(&restarted).await;let done=wait(&restarted,&recovery).await;assert_eq!(done.status,JobStatus::Done,"{done:?}");
 // Owner-only paginated history must not expose results after source access is revoked.
 let router=support::router(restarted.clone());let req=Request::builder().uri("/api/compositions/filmcraft/analysis-jobs?limit=1").header("authorization",format!("Bearer {}",owner.token)).body(Body::empty()).unwrap();let response=router.clone().oneshot(req).await.unwrap();assert_eq!(response.status(),StatusCode::OK);let page:Value=serde_json::from_slice(&to_bytes(response.into_body(),1024*1024).await.unwrap()).unwrap();assert_eq!(page["jobs"].as_array().unwrap().len(),1);let cursor=page["nextCursor"].as_str().unwrap();let req=Request::builder().uri(format!("/api/compositions/filmcraft/analysis-jobs?limit=1&cursor={cursor}")).header("authorization",format!("Bearer {}",owner.token)).body(Body::empty()).unwrap();let response=router.clone().oneshot(req).await.unwrap();let next:Value=serde_json::from_slice(&to_bytes(response.into_body(),1024*1024).await.unwrap()).unwrap();assert_ne!(next["jobs"][0]["jobId"],page["jobs"][0]["jobId"]);
 let space=restarted.db.create_space(&outsider.user.username,"Revoked analysis source").await.unwrap();restarted.db.create_space_composition_project("Claim source",&json!({"schemaVersion":1,"sources":{"analysis-source":{"id":"analysis-source"}}}),&["analysis-source".into()],&outsider.user.username,&space.id).await.unwrap();
 let req=Request::builder().uri("/api/compositions/filmcraft/analysis-jobs").header("authorization",format!("Bearer {}",owner.token)).body(Body::empty()).unwrap();let response=router.clone().oneshot(req).await.unwrap();let page:Value=serde_json::from_slice(&to_bytes(response.into_body(),1024*1024).await.unwrap()).unwrap();assert!(page["jobs"].as_array().unwrap().is_empty());let req=Request::builder().uri(format!("/api/jobs/{recovery}")).header("authorization",format!("Bearer {}",owner.token)).body(Body::empty()).unwrap();assert_eq!(router.oneshot(req).await.unwrap().status(),StatusCode::FORBIDDEN);
 restarted.begin_shutdown();assert!(restarted.wait_for_tasks(std::time::Duration::from_secs(5)).await);
}
#[tokio::test]async fn long_analysis_reports_progress_beyond_foreground_preview_deadline(){
 let(state,_dir)=support::make_state(false,false).await;let fixture:Value=serde_json::from_reader(flate2::read::GzDecoder::new(std::fs::File::open(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/filmcraft-source-stabilizer.json.gz")).unwrap())).unwrap();let mut document=fixture["cases"][0]["document"].clone();
 document["project"]["items"]["6"]["kind"]["Sequence"]["video_tracks"][0]["items"][0]["duration"]=json!(120i64*254_016_000_000);document["project"]["items"]["1"]["kind"]["Media"]["info"]["duration"]=json!(122i64*254_016_000_000);
 let movie=state.storage.join("sources/long-analysis.mov");let out=std::process::Command::new("ffmpeg").args(["-nostdin","-v","error","-f","lavfi","-i","testsrc=size=96x64:rate=6:duration=122","-c:v","qtrle","-pix_fmt","argb","-threads","1"]).arg(&movie).output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));
 assert!(state.library.add(video_kadr_backend::library::MediaEntry::from_result("source",&json!({"id":"long-analysis","filename":"long-analysis.mov","mediaType":"video"}))).await);let owner=state.db.register_auth_user("long-analysis-owner","analysis test password").await.unwrap().unwrap();let input=json!({"document":serde_json::to_string(&document).unwrap(),"sequenceId":"6","timeTicks":"63504000000","captions":false,"sources":{"1":"long-analysis"}});let app=support::router(state.clone());let start=std::time::Instant::now();let id=submit(&app,&input,&owner.token).await;
 let pool=sqlx::sqlite::SqlitePoolOptions::new().max_connections(1).connect_with(sqlx::sqlite::SqliteConnectOptions::new().filename(state.storage.join("app.db"))).await.unwrap();
 let saved=tokio::time::timeout(std::time::Duration::from_secs(60),async{loop{let bytes:Option<Vec<u8>>=sqlx::query_scalar("SELECT state_json FROM stabilization_checkpoints WHERE job_id=?").bind(&id).fetch_optional(&pool).await.unwrap();if let Some(bytes)=bytes{use sha2::Digest;assert_eq!(sha2::Sha256::digest(&bytes[32..]).as_slice(),&bytes[..32]);let snapshot:Value=serde_json::from_slice(&bytes[32..]).unwrap();assert!(!String::from_utf8_lossy(&bytes[32..]).contains("px"));let next=snapshot[0][1]["next"].as_u64().unwrap();if next>=36{break next}}tokio::time::sleep(std::time::Duration::from_millis(25)).await;}}).await.unwrap();
 state.begin_shutdown();assert!(state.wait_for_tasks(std::time::Duration::from_secs(5)).await);assert_eq!(state.get_job(&id).await.unwrap().unwrap().status,JobStatus::Running);
 let state=AppState::new_with_runtime(state.storage.clone(),2,(*state.tools).clone(),video_kadr_backend::library::Library::load(state.storage.clone()).await,video_kadr_backend::db::Db::open(&state.storage).await.unwrap(),state.encode_budget,2).unwrap();state.recover_jobs().await;assert_eq!(state.get_job(&id).await.unwrap().unwrap().status,JobStatus::Pending);video_kadr_backend::handlers::resume_pending_jobs(&state).await;let app=support::router(state.clone());let mut saw_progress=false;let job=tokio::time::timeout(std::time::Duration::from_secs(180),async{loop{let job=state.get_job(&id).await.unwrap().unwrap();if job.progress.is_some_and(|p|p>0.&&p<100.){saw_progress=true}if matches!(job.status,JobStatus::Done|JobStatus::Error|JobStatus::Cancelled){break job}tokio::time::sleep(std::time::Duration::from_millis(25)).await;}}).await.unwrap();assert_eq!(job.status,JobStatus::Done,"{job:?}");assert!(saw_progress,"long analysis must publish intermediate progress");assert!(job.result.as_ref().unwrap()["analysisResumedFrames"].as_u64().unwrap()>=saved,"must use persisted prefix");let checkpoints:i64=sqlx::query_scalar("SELECT COUNT(*) FROM stabilization_checkpoints WHERE job_id=?").bind(&id).fetch_one(&pool).await.unwrap();assert_eq!(checkpoints,0,"successful job must release its checkpoint");eprintln!("720-frame background analysis completed in {:?}",start.elapsed());let hits=state.filmcraft_video_previews.stabilization_path_cache_stats().unwrap().2;assert_eq!(app.oneshot(post("/api/compositions/filmcraft/preview-frame",input,Some(&owner.token))).await.unwrap().status(),StatusCode::OK);assert_eq!(state.filmcraft_video_previews.stabilization_path_cache_stats().unwrap().2,hits+1);state.begin_shutdown();assert!(state.wait_for_tasks(std::time::Duration::from_secs(5)).await);
}
struct WorkerProcess(std::process::Child);
impl Drop for WorkerProcess{fn drop(&mut self){let _=self.0.kill();let _=self.0.wait();}}
fn worker(storage:&std::path::Path,id:&str,label:&str)->WorkerProcess{
 let log=std::fs::File::create(storage.join(format!("worker-{label}.log"))).unwrap();
 WorkerProcess(std::process::Command::new(std::env::current_exe().unwrap()).args(["--ignored","--exact","checkpoint_worker_process","--nocapture"]).env("VIDEO_KADR_CHECKPOINT_STORAGE",storage).env("VIDEO_KADR_CHECKPOINT_JOB",id).stdout(std::process::Stdio::from(log.try_clone().unwrap())).stderr(std::process::Stdio::from(log)).spawn().unwrap())
}
async fn reopen(storage:std::path::PathBuf)->AppState{
 use video_kadr_backend::config::encode_budget::{EncodeBudget,EncodeProfile,RuntimeLimits};
 let budget=EncodeBudget::for_profile(EncodeProfile::Balanced,RuntimeLimits{logical_cpus:2,memory_mib:Some(1024)}).unwrap();
 AppState::new_with_runtime(storage.clone(),2,video_kadr_backend::state::ToolInfo::default(),video_kadr_backend::library::Library::load(storage.clone()).await,video_kadr_backend::db::Db::open(&storage).await.unwrap(),budget,2).unwrap()
}
/// Explicitly invoked by the crash test in a disposable child process.
#[tokio::test]#[ignore]
async fn checkpoint_worker_process(){
 let storage=std::path::PathBuf::from(std::env::var_os("VIDEO_KADR_CHECKPOINT_STORAGE").expect("worker storage"));let id=std::env::var("VIDEO_KADR_CHECKPOINT_JOB").unwrap();
 let state=reopen(storage.clone()).await;state.recover_jobs().await;video_kadr_backend::handlers::resume_pending_jobs(&state).await;
 let job=tokio::time::timeout(std::time::Duration::from_secs(180),async{loop{let job=state.get_job(&id).await.unwrap().unwrap();if matches!(job.status,JobStatus::Done|JobStatus::Error|JobStatus::Cancelled){break job}tokio::time::sleep(std::time::Duration::from_millis(25)).await;}}).await.unwrap();
 std::fs::write(storage.join("worker-result.json"),serde_json::to_vec(&job).unwrap()).unwrap();assert_eq!(job.status,JobStatus::Done,"{job:?}");state.begin_shutdown();assert!(state.wait_for_tasks(std::time::Duration::from_secs(5)).await);
}
#[tokio::test]async fn killed_worker_resumes_committed_prefix_in_new_process(){
 let(state,_dir)=support::make_state(false,false).await;let fixture:Value=serde_json::from_reader(flate2::read::GzDecoder::new(std::fs::File::open(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/filmcraft-source-stabilizer.json.gz")).unwrap())).unwrap();let mut document=fixture["cases"][0]["document"].clone();document["project"]["items"]["6"]["kind"]["Sequence"]["video_tracks"][0]["items"][0]["duration"]=json!(120i64*254_016_000_000);document["project"]["items"]["1"]["kind"]["Media"]["info"]["duration"]=json!(122i64*254_016_000_000);
 let tracks=document["project"]["items"]["6"]["kind"]["Sequence"]["video_tracks"].as_array_mut().unwrap();let mut short=tracks[0].clone();short["id"]=json!(9090);short["name"]=json!("Already analysed");short["items"][0]["id"]=json!(9091);short["items"][0]["duration"]=json!(254_016_000_000i64);tracks.insert(0,short);
 let movie=state.storage.join("sources/crash-analysis.mov");let out=std::process::Command::new("ffmpeg").args(["-nostdin","-v","error","-f","lavfi","-i","testsrc=size=96x64:rate=6:duration=122","-c:v","qtrle","-pix_fmt","argb","-threads","1"]).arg(&movie).output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));
 assert!(state.library.add(video_kadr_backend::library::MediaEntry::from_result("source",&json!({"id":"crash-analysis","filename":"crash-analysis.mov","mediaType":"video"}))).await);let owner=state.db.register_auth_user("crash-analysis-owner","analysis test password").await.unwrap().unwrap();let input=json!({"document":serde_json::to_string(&document).unwrap(),"sequenceId":"6","timeTicks":"63504000000","captions":false,"sources":{"1":"crash-analysis"}});
 let mut permits=vec![];for _ in 0..state.resource_limit(video_kadr_backend::config::resource_classes::ResourceClass::Analysis){permits.push(state.acquire_job_slot(video_kadr_backend::config::resource_classes::ResourceClass::Analysis).await.unwrap());}let app=support::router(state.clone());let id=submit(&app,&input,&owner.token).await;state.begin_shutdown();drop(permits);assert!(state.wait_for_tasks(std::time::Duration::from_secs(5)).await);
 let pool=sqlx::sqlite::SqlitePoolOptions::new().max_connections(1).connect_with(sqlx::sqlite::SqliteConnectOptions::new().filename(state.storage.join("app.db"))).await.unwrap();
 let mut first=worker(&state.storage,&id,"killed");
 let saved=tokio::time::timeout(std::time::Duration::from_secs(60),async{loop{if let Some(status)=first.0.try_wait().unwrap(){panic!("worker ended before checkpoint: {status}; {}",std::fs::read_to_string(state.storage.join("worker-killed.log")).unwrap())}let bytes:Option<Vec<u8>>=sqlx::query_scalar("SELECT state_json FROM stabilization_checkpoints WHERE job_id=?").bind(&id).fetch_optional(&pool).await.unwrap();if let Some(bytes)=bytes{use sha2::Digest;assert_eq!(sha2::Sha256::digest(&bytes[32..]).as_slice(),&bytes[..32]);let snapshot:Value=serde_json::from_slice(&bytes[32..]).unwrap();let next=snapshot[0][1]["next"].as_u64().unwrap();if next>=36{break next}}tokio::time::sleep(std::time::Duration::from_millis(25)).await;}}).await.expect("worker checkpoint");
 assert!(std::fs::read_dir(state.storage.join("cache/stabilizer-v1")).unwrap().any(|entry|entry.unwrap().path().extension().and_then(|e|e.to_str())==Some("trajectory")),"completed first clip must persist before second clip finishes");
 first.0.kill().unwrap();let killed=first.0.wait().unwrap();assert!(!killed.success());#[cfg(unix)]{use std::os::unix::process::ExitStatusExt;assert_eq!(killed.signal(),Some(9));}assert!(!state.storage.join("worker-result.json").exists());
 let status:String=sqlx::query_scalar("SELECT status FROM jobs WHERE id=?").bind(&id).fetch_one(&pool).await.unwrap();assert_eq!(status,"running");
 let mut second=worker(&state.storage,&id,"resumed");let status=tokio::time::timeout(std::time::Duration::from_secs(180),async{loop{if let Some(status)=second.0.try_wait().unwrap(){break status}tokio::time::sleep(std::time::Duration::from_millis(25)).await;}}).await.expect("restarted worker terminal");assert!(status.success(),"{}",std::fs::read_to_string(state.storage.join("worker-resumed.log")).unwrap());let job:Value=serde_json::from_slice(&std::fs::read(state.storage.join("worker-result.json")).unwrap()).unwrap();assert_eq!(job["status"],"done");assert!(job["result"]["analysisResumedFrames"].as_u64().unwrap()>=saved,"{job}");assert!(job["result"]["analysisReusedPaths"].as_u64().unwrap()>=1,"completed clip must be restored from disk: {job}");let checkpoints:i64=sqlx::query_scalar("SELECT COUNT(*) FROM stabilization_checkpoints WHERE job_id=?").bind(&id).fetch_one(&pool).await.unwrap();assert_eq!(checkpoints,0);eprintln!("SIGKILL recovery retained at least {saved} committed analysis frames");
}
